| huma | 79 | 63 | 63 | 64 | +1 | 1 |
| cli | 10 | 10 | 10 | 10 | 0 | 0 |
| entire-api | 30 | 18 | 18 | 21 | +3 | 3 |
| entiredb | 95 | 85 | 85 | 93 | +8 | 8 |

