erived.", "sections": [{"files": ["internal/sem/records_cache.go", "internal/sem/search_cache.go", "internal/sem/search_cache_cold_complete_test.go", "internal/sem/cache_stream_test.go"], "title": "Cache keying and cold builds", "description": "Committed-tree caches are keyed on the checkout-relative scope. A cold cached query honours --max-indexed-files. A cold committed-tree query persists the complete snapshot, and concurrent cold builds are serialised across processes. A warm cache hit reports the same coverage diagnostics as a cold one."}, {"files": ["internal/sem/search_related.go", "internal/sem/search_callee.go", "internal/sem/search_enclosure.go", "internal/sem/search_verify_scope_native_test.go", "internal/sem/search_related_declaration_test.go"], "title": "VERIFY derivation and related search", "description": "VERIFY is derived from manifests above a subdirectory --repo, and the file inventory carries into that walk. Related-declaration and callee/enclosure search handling changed."}]}, {"title": "CLI behavior", "summary": "The `def`, `query` and `edges` commands now handle budgets and cache dirs more consistently, and the exact-name matcher is fixed.", "sections": [{"files": ["internal/cli/def.go", "internal/cli/def_budget_test.go", "internal/cli/def_cache_dir_test.go"], "title": "def and edges", "description": "`def` resolves its cache dir through resolveCacheDir. It holds to --max-context-bytes on every output path, and its JSON answers keep fitting when one name cannot fit. Targeted `edges` queries honour --cache-dir."}, {"files": ["internal/cli/search.go", "internal/cli/search_exact_name.go", "internal/cli/search_agent_complete_test.go", "internal/cli/search_exact_name_return_type_test.go"], "title": "query output and exact-name lookup", "description": "Rework of agent-format completeness and marker handling, plus a pinned unmarked-source fallback contract. Go result types are no longer treated as exact-name method definitions."}]}, {"title": "Stats,