"2026-10-12T14:53:23.172Z", "status_source": "comment_patch", "status_actor_kind": "human", "stale_outcome": "stale", "stale_checked_at": "2026-10-12T14:50:49.770Z", "stale_checked_code_version_id": "01M4R9GK0CA5BMDT5KSC4659Q2", "client_id": "627a59d98e5b8104e2ab8f3490921255", "client_id_hash": "f4a97f7dc0b1e6a0af05d6d6fc31f5b724a9a601fa014376d5145713b4cdbc5f", "created_at": "2026-10-12T14:32:52.753Z", "updated_at": "2026-10-12T14:53:23.172Z", "location": {"id": "01M4R8FQ8KZB84D7RX9V850P9X", "review_comment_id": "01M4R8FQ8KAN2MJRGGAWQY0Q3H", "code_version_id": "01M4R8D9D9J8QC5P2CVDG9M148", "granularity": "range", "file_path": "internal/sem/search_semantic.go", "start_line": 1236, "start_column": null, "end_line": 1259, "end_column": null, "selected_text": "func semanticLoopbackDial(ctx context.Context, network, address string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(address)
	if err != nil {
		return nil, errSemanticNotLoopback
	}
	var targets []string
	switch {
	case strings.EqualFold(host, "localhost"):
		targets = []string{"127.0.0.1", "::1"}
	case semanticLoopbackHost(host):
		targets = []string{host}
	default:
		return nil, errSemanticNotLoopback
	}
	dialer := &net.Dialer{Timeout: 5 * time.Second}
	var lastErr error
	for _, target := range targets {
		conn, err := dialer.DialContext(ctx, network, net.JoinHostPort(target, port))
		if err == nil {
			return conn, nil
		}
		lastErr = err
	}
	return nil, lastErr", "nearby_text": null, "language": null}}, {"discussion_id": "01M4R8DTTZ01MRF4MKM0RDCXCE", "discussion_message_count": 0, "id": "01M4R8DTTZKAAE270K8GFDW7WE", "trail_id": "01M3P25ZTS4E5R83CBJ11A9VAS", "repo_id": "01KXJQJRF3YPN2MGMFFDTHZVPK", "review_id": "01M4R8DTQZB68V6813S2Y9443G", "code_version_id": "01M4R8D9D9J8QC5P2CVDG9M148", "actor_id": "01KSAMGR8YW1KR3RF03RC70K93", "actor_display_name": "ashtom", "actor_identity": {"kind": "account", "account_id": "01KSAMGR8YW1KR3RF03RC70K93", "display_name": "Thomas Dohmke", "avatar_url": "https://avatars.githubusercontent.com/u/70720?v=4", "handles": [{"provider": "github", "handle": "ashtom", "is_primary": true}]}, "body": "Indexing reads up to 256 MiB per embedding batch into memory and decodes it with json.Unmarshal into [][]float64. A local server returning a body of `0,0,0,...` inflates to roughly 1-2 GB of memory, a crash risk. Cap the response size relative to the expected batch size and dimension, or stream-decode it.", "severity": "low", "confidence": 0.6, "status": "resolved", "status_reason": "Embedding decoding now rejects excess rows and coordinates while decoding, before allocating a huge float slice, and raw body limits scale with requested rows and maximum dimension. Added oversized-vector/extra-row/duplicate/trailing-data regressions; all Semantic tests pass.", "status_actor_id": "01KSAMGR8YW1KR3RF03RC70K93", "status_actor_display_name": "ashtom", "status_actor_identity": {"kind": "account", "account_id": "01KSAMGR8YW1KR3RF03RC70K93", "display_name": "Thomas Dohmke", "avatar_url": "https://avatars.githubusercontent.com/u/70720?v=4", "handles": [{"provider": "github", "handle": "ashtom", "is_primary": true}]}, "status_changed_at": "2026-10-12T14:52:57.382Z", "status_source": "comment_patch", "status_actor_kind": "human", "stale_outcome": "stale", "stale_checked_at": "2026-10-12T14:36:43.880Z", "stale_checked_code_version_id": "01M4R8PRY9QENF86S7WW74GZF6", "client_id": "advsec-20261012-22